{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/support-channels.json
    Ways to get help as cards or rows, each with an icon, a title, a sentence and an open link. Axes: layout (grid, list), columns, action (link, none), tone (default, muted).
    Props (p): id, title, channels, empty, open, layout, cols, action, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_channels = ($p['channels'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_open = ($p['open'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_action = ($p['action'] ?? 'link')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {if og_t(og_eq(og_len($v_channels), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'life-buoy', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_7}
      {foreach og_l($v_channels) as $v_c}
        {capture $c_6}
          {capture $c_5}
            {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_c, ['icon'])), 'size' => 24])|noescape}
            {capture $c_3}
              {capture $c_1}
                {=og_text(og_get($v_c, ['title']))}
              {/capture}
              {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'base', 'weight' => 'bold', 'children' => (string) $c_1])|noescape}
              {capture $c_2}
                {=og_text(og_get($v_c, ['text']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'flex-1', 'children' => (string) $c_3])|noescape}
            {if og_t(og_eq($v_action, 'link'))}
              {capture $c_4}
                {=og_text($v_open)}
              {/capture}
              {=og_include('blocks/menu-entry.latte', ['p' => ['href' => og_get($v_c, ['href']), 'className' => og_cnv(['font-semibold']), 'testid' => 'open'], 'children' => og_markup($c_4)])|noescape}
            {/if}
          {/capture}
          {=og_include('compose/CardContent.latte', ['class' => og_s(og_cnv(['flex flex-1 gap-4', (og_t(og_eq($v_layout, 'list')) ? 'items-center' : 'flex-col')])), 'children' => (string) $c_5])|noescape}
        {/capture}
        {=og_include('compose/Card.latte', ['variant' => 'default', 'class' => og_s(og_cnv(['h-full', (og_t(og_eq($v_layout, 'list')) ? 'flex-row items-center' : '')])), 'children' => (string) $c_6])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_layout, 'list')) ? '1' : $v_cols)), 'class' => 'gap-4', 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_7])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_8)])|noescape}
